## 应用层架构

### 1. Agent 类实现

**文件**: `src/agent/index.ts`

#### 核心属性

```typescript
export default class Agent extends EventEmitter {
  llmProvider: LLMProvider;       // LLM 提供商
  sessionManager: SessionManager; // 会话管理器
  systemPrompt: string;           // 系统提示词
  defaultTools: ToolSchema[];     // 默认工具列表
  maxLoop: number;                // 最大迭代次数 (默认 1024)
  noProgressLimit: number;        // 连续错误阈值 (默认 2)
}
```

#### 执行流程

```mermaid
graph TD
    A[用户输入] --> B[agent.run]
    B --> C[添加消息到会话]
    C --> D[主循环 Loop]
    D --> E{循环次数 < maxLoop?}
    E -->|否| F[达到最大迭代次数]
    E -->|是| G[获取历史消息]
    G --> H[调用 LLM]
    H --> I[解析响应]
    I --> J{有工具调用?}
    J -->|是| K[handleToolCalls]
    K --> L[并行执行工具]
    L --> M[添加工具结果到会话]
    M --> D
    J -->|否| N[检查完成原因]
    N --> O{完成原因正常?}
    O -->|是| P[返回助手响应]
    O -->|否| Q[记录错误]
    Q --> R{连续错误 >= 阈值?}
    R -->|是| S[终止执行]
    R -->|否| D
```

#### 关键代码片段

**主循环** (lines 162-257):

```typescript
async run(query: string, streamCallback?: StreamCallback): Promise<string> {
  let consecutiveErrors = 0;
  let loopCount = 0;

  // 添加用户消息
  await this.sessionManager.addMessage({
    role: 'user',
    content: query,
    type: 'text'
  });

  while (loopCount < this.maxLoop) {
    loopCount++;

    // 获取消息
    const messages = this.sessionManager.getMessages();

    // 调用 LLM
    const response = await this.llmProvider.generate(messages, {
      system_prompt: this.systemPrompt,
      tools: this.defaultTools,
      stream: true,
      streamCallback: streamCallback ? (chunk) => {
        this.emit('stream-chunk', chunk);
        streamCallback(chunk);
      } : undefined
    });

    if (!response) {
      consecutiveErrors++;
      if (consecutiveErrors >= this.noProgressLimit) {
        throw new Error('Too many consecutive failures');
      }
      continue;
    }

    // 添加助手消息
    await this.sessionManager.addMessage(response);

    // 检查工具调用
    if (response.tool_calls && response.tool_calls.length > 0) {
      const results = await this.handleToolCalls(response.tool_calls);
      consecutiveErrors = 0;
      continue;
    }

    // 检查完成原因
    if (response.finishReason !== 'stop') {
      throw new Error(`Unexpected finish reason: ${response.finishReason}`);
    }

    return response.content;
  }

  throw new Error('Maximum loop count exceeded');
}
```

**工具执行** (lines 82-137):

```typescript
private async executeToolCall(toolCall: ToolCall): Promise<string> {
  const { name, arguments: args } = toolCall.function;
  const result = await ToolRegistry.execute(name, args);

  // 格式化工具结果
  const summary = `[Tool: ${name}] ${result}`;

  await this.sessionManager.addMessage({
    role: 'tool',
    content: summary,
    type: 'tool',
    tool_call_id: toolCall.id
  });

  return summary;
}

private async handleToolCalls(toolCalls: ToolCall[]): Promise<string[]> {
  // 并行执行所有工具
  const results = await Promise.all(
    toolCalls.map(call => this.executeToolCall(call))
  );

  return results;
}
```

