private async chatMode(input: string) {
  try {
    const spinner = ora('思考中...').start();

    await this.context.agent.run(input, (chunk) => {
      spinner.stop();
      if (chunk.content) {
        process.stdout.write(chunk.content);
      }
    });

    console.log();
  } catch (error) {
    console.error('Error:', error.message);
  }
}
