private async loadSkill(skillPath: string): Promise<void> {
  const content = readFileSync(skillPath, 'utf-8');
  const { data, content: body } = matter(content);

  // 验证格式
  if (!data.name || !data.description) {
    throw new Error('Invalid skill format');
  }

  // 验证名称格式
  if (!/^[a-z0-9-]+$/.test(data.name)) {
    throw new Error('Skill name must be lowercase alphanumeric with dashes');
  }

  this.skills.set(data.name, {
    name: data.name,
    description: data.description,
    path: dirname(skillPath)
  });
}
```

#### 热重载

```typescript
private async startHotReload(): Promise<void> {
  setInterval(async () => {
    const currentFiles = await this.listSkillFiles();

    // 检测新增/修改
    for (const file of currentFiles) {
      const stat = await fs.stat(file);
      const lastModified = this.skillCache.get(file);

      if (!lastModified || stat.mtime > lastModified) {
        await this.loadSkill(file);
        this.skillCache.set(file, stat.mtime);
      }
    }

    // 检测删除
    for (const [file, mtime] of this.skillCache) {
      if (!currentFiles.includes(file)) {
        await this.removeSkill(file);
        this.skillCache.delete(file);
      }
    }
  }, 1000);
}
```

