export class SkillTool extends BaseTool<z.ZodTypeAny> {
  name = 'skill';
  description = 'Load and execute skills';

  // 动态生成描述
  getDescription(): string {
    const skills = Array.from(loader.skills.values());
    const skillsList = skills
      .map(s => `<skill><name>${s.name}</name><description>${s.description}</description></skill>`)
      .join('\n  ');

    return `Available skills:\n<available_skills>\n  ${skillsList}\n</available_skills>`;
