private async persistMessages(): Promise<void> {
  const messagesPath = join(this.sessionPath, 'messages.json');
  const cachePath = join(this.sessionPath, 'cache.md');

  // 保存完整 JSON
  await writeFile(messagesPath, JSON.stringify(this.messageList, null, 2));

  // 追加日志
  const lastMessage = this.messageList[this.messageList.length - 1];
  const logEntry = `[${new Date().toISOString()}] ${lastMessage.role}: ${lastMessage.content}`;
  await appendFile(cachePath, logEntry + '\n');
}
