#### 触发机制

```typescript
export class CompactionEngine {
  maxTokens: number;
  maxOutputTokens: number;
  triggerRatio: number = 0.10;  // 剩余 10% 时触发

  shouldCompact(messageList: Message[]): boolean {
    const currentTokens = this.estimateTokens(messageList);
    const availableTokens = this.maxTokens - currentTokens;

    return availableTokens < this.maxTokens * this.triggerRatio;
  }
}
```

#### 压缩策略

```typescript
async compact(messages: Message[]): Promise<Message[]> {
  // 1. 保护区策略: 保留最近 6 条消息
  const protectedCount = 6;
  const recentMessages = messages.slice(-protectedCount);

  // 2. 历史摘要
  const historyMessages = messages.slice(0, -protectedCount);

  // 3. LLM 摘要
  const summary = await this.summarizeHistory(historyMessages);

  // 4. 组合结果
  return [
    { role: 'system', content: summary, type: 'summary' },
    ...recentMessages
  ];
}
```

#### 工具调用处理

```typescript
private adjustForToolCalls(messages: Message[]): Message[] {
  const result = [];
  const toolCallMap = new Map<string, Message>();

  // 收集 tool_call 和 tool 消息对
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    if (msg.tool_call_id) {
      toolCallMap.set(msg.tool_call_id, msg);
    } else if (msg.tool_calls) {
      const response = msg.tool_calls.map(tc => {
        const responseMsg = toolCallMap.get(tc.id);
        return responseMsg ? `[Tool: ${tc.function.name}] ${responseMsg.content}` : '';
      }).join('\n');

      // 合并为一条消息
      result.unshift({
        ...msg,
        content: `${msg.content}\n\nTool responses:\n${response}`
      });
    } else {
      result.unshift(msg);
    }
  }

  return result;
}
```

