#### 3.3.4 ToolRegistry (工具注册中心)

**文件**: `src/tool/registry.ts:8-410`

**单例模式**:
```typescript
class ToolRegistry {
  private static instance: ToolRegistry;
  private tools: Map<string, BaseTool<any>> = new Map();
  private context: {
    sessionId?: string;
    sessionPath?: string;
    allowedTools?: string[];
  } = {};

  static getInstance(): ToolRegistry {
    if (!ToolRegistry.instance) {
      ToolRegistry.instance = new ToolRegistry();
    }
    return ToolRegistry.instance;
  }
}
```

**核心方法**:

**注册工具** (`lines 33-41`):
```typescript
static register<T extends BaseTool<any>>(tool: T | T[]): void {
  const tools = Array.isArray(tool) ? tool : [tool];
  for (const t of tools) {
    if (this.tools.has(t.name)) {
      throw new Error(`Tool "${t.name}" is already registered`);
    }
    this.tools.set(t.name, t);
  }
}
```

**获取工具** (`lines 43-52`):
```typescript
static get(name: string): BaseTool<any> {
  const tool = this.tools.get(name);
  if (!tool) {
    throw new Error(`Tool "${name}" not found`);
  }
  return tool;
}
```

**执行工具** (`lines 129-154`):
```typescript
static async execute(name: string, args: string): Promise<ToolOutput> {
  const tool = this.get(name);

  // 权限检查
  const allowed = this.context.allowedTools;
  if (allowed && !allowed.includes(name)) {
    return `Tool "${name}" is not allowed`;
  }

  // 解析和验证参数
  const argsObj = JSON.parse(args);
  const parsed = tool.schema.safeParse(argsObj);

  if (!parsed.success) {
    return `Invalid arguments: ${parsed.error.errors
      .map(e => `${e.path.join('.')}: ${e.message}`)
      .join(', ')}`;
  }

  return await tool.execute(parsed.data);
}
```

**Schema 生成** (`lines 165-189`):
```typescript
static getSchemas(): ToolSchema[] {
  return Array.from(this.tools.values()).map(tool => {
    const jsonSchema = zodToJsonSchema(tool.schema);
    return {
      type: 'function',
      function: {
        name: tool.name,
        description: tool.description,
        parameters: {
          ...jsonSchema,
          strict: true
        }
      }
    };
  });
}
