#### 3.3.5 Zod 到 JSON Schema 转换

**文件**: `src/tool/registry.ts:197-406`

**支持的类型映射**:
| Zod 类型 | JSON Schema | 示例 |
|---------|------------|------|
| `ZodString` | `{ type: 'string' }` | `"hello"` |
| `ZodNumber` | `{ type: 'number' }` | `42` |
| `ZodBoolean` | `{ type: 'boolean' }` | `true` |
| `ZodArray` | `{ type: 'array', items: ... }` | `["a", "b"]` |
| `ZodObject` | `{ type: 'object', properties: ... }` | `{ a: 1 }` |
| `ZodUnion` | `{ oneOf: [...] }` | `1 \|\| "a"` |
| `ZodDiscriminatedUnion` | `{ oneOf: [...], examples: [...] }` | `{ type: 'a' }` |
| `ZodOptional` | 移除 `required` 字段 | `{ a?: string }` |
| `ZodEnum` | `{ enum: [...] }` | `"red" \| "green"` |

**示例生成算法** (`lines 347-406`):
```typescript
private static generateExample(schema: z.ZodTypeAny, fieldName?: string): any {
  // 根据字段名生成上下文感知的值
  if (fieldName === 'content') return 'example content';
  if (fieldName === 'status') return 'pending';
  if (fieldName === 'priority') return 'high';

  // 处理枚举
  if (schema instanceof ZodEnum) {
    return schema.options[0];
  }

  // 递归处理嵌套对象
  if (schema instanceof ZodObject) {
    const result: any = {};
    for (const [key, value] of Object.entries(schema.shape)) {
      result[key] = this.generateExample(value as ZodTypeAny, key);
    }
    return result;
  }

  // 默认值
  return 'example';
}
```

